CREATE FUNCTION public.tax_impact_access(_tenant_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND public.is_ta_master(auth.uid()) AND EXISTS (SELECT 1 FROM public.tenants WHERE id = _tenant_id) AND public.can_see_tenant(auth.uid(), _tenant_id) AND public.is_module_enabled_for_user(auth.uid(), _tenant_id, 'tax_impact_check') $$;
REVOKE ALL ON FUNCTION public.tax_impact_access(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.tax_impact_access(uuid) TO authenticated, service_role;
CREATE TABLE public.tax_impact_analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_tenant_id uuid NOT NULL REFERENCES public.tenants(id), name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,client_tenant_id));
GRANT SELECT, INSERT ON public.tax_impact_analyses TO authenticated;
GRANT ALL ON public.tax_impact_analyses TO service_role;
ALTER TABLE public.tax_impact_analyses ENABLE ROW LEVEL SECURITY;
CREATE POLICY tax_analysis_read ON public.tax_impact_analyses FOR SELECT TO authenticated USING (public.tax_impact_access(client_tenant_id));
CREATE POLICY tax_analysis_insert ON public.tax_impact_analyses FOR INSERT TO authenticated WITH CHECK (public.tax_impact_access(client_tenant_id) AND created_by=auth.uid());
CREATE TABLE public.tax_impact_imports (id uuid PRIMARY KEY, analysis_id uuid NOT NULL, client_tenant_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('baseline','proposal')), filename text NOT NULL, storage_path text NOT NULL UNIQUE, file_hash text NOT NULL, sheet text NOT NULL, header_row integer NOT NULL, mapping jsonb NOT NULL, period_year integer NOT NULL, rows jsonb NOT NULL, errors jsonb NOT NULL DEFAULT '[]', created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(analysis_id,client_tenant_id) REFERENCES public.tax_impact_analyses(id,client_tenant_id), UNIQUE(id,analysis_id,client_tenant_id), CHECK(storage_path=client_tenant_id::text || '/' || analysis_id::text || '/' || id::text || '.xlsx'));
GRANT SELECT, INSERT ON public.tax_impact_imports TO authenticated;
GRANT ALL ON public.tax_impact_imports TO service_role;
ALTER TABLE public.tax_impact_imports ENABLE ROW LEVEL SECURITY;
CREATE POLICY tax_import_read ON public.tax_impact_imports FOR SELECT TO authenticated USING (public.tax_impact_access(client_tenant_id));
CREATE POLICY tax_import_insert ON public.tax_impact_imports FOR INSERT TO authenticated WITH CHECK (public.tax_impact_access(client_tenant_id) AND created_by=auth.uid());
CREATE TABLE public.tax_impact_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), analysis_id uuid NOT NULL, client_tenant_id uuid NOT NULL, version integer NOT NULL CHECK(version > 0), baseline_import_id uuid NOT NULL, proposal_import_id uuid NOT NULL, manual_matches jsonb NOT NULL DEFAULT '{}', results jsonb NOT NULL, status text NOT NULL DEFAULT 'compared' CHECK(status IN ('compared','needs_review')), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(analysis_id,client_tenant_id) REFERENCES public.tax_impact_analyses(id,client_tenant_id), FOREIGN KEY(baseline_import_id,analysis_id,client_tenant_id) REFERENCES public.tax_impact_imports(id,analysis_id,client_tenant_id), FOREIGN KEY(proposal_import_id,analysis_id,client_tenant_id) REFERENCES public.tax_impact_imports(id,analysis_id,client_tenant_id), UNIQUE(analysis_id,version));
GRANT SELECT, INSERT ON public.tax_impact_revisions TO authenticated;
GRANT ALL ON public.tax_impact_revisions TO service_role;
ALTER TABLE public.tax_impact_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY tax_revision_read ON public.tax_impact_revisions FOR SELECT TO authenticated USING (public.tax_impact_access(client_tenant_id));
CREATE POLICY tax_revision_insert ON public.tax_impact_revisions FOR INSERT TO authenticated WITH CHECK (public.tax_impact_access(client_tenant_id) AND created_by=auth.uid());
CREATE TABLE public.tax_impact_mapping_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_tenant_id uuid NOT NULL REFERENCES public.tenants(id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200), role text NOT NULL CHECK(role IN ('baseline','proposal')), mapping jsonb NOT NULL, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.tax_impact_mapping_profiles TO authenticated;
GRANT ALL ON public.tax_impact_mapping_profiles TO service_role;
ALTER TABLE public.tax_impact_mapping_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY tax_profile_read ON public.tax_impact_mapping_profiles FOR SELECT TO authenticated USING (public.tax_impact_access(client_tenant_id));
CREATE POLICY tax_profile_insert ON public.tax_impact_mapping_profiles FOR INSERT TO authenticated WITH CHECK (public.tax_impact_access(client_tenant_id) AND created_by=auth.uid());
CREATE INDEX tax_analyses_tenant ON public.tax_impact_analyses(client_tenant_id,created_at DESC);
CREATE INDEX tax_imports_analysis ON public.tax_impact_imports(analysis_id,created_at DESC);
CREATE INDEX tax_revisions_analysis ON public.tax_impact_revisions(analysis_id,version DESC);
CREATE POLICY tax_original_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='tax-impact-originals' AND EXISTS (SELECT 1 FROM public.tax_impact_analyses a WHERE a.client_tenant_id::text=(storage.foldername(name))[1] AND a.id::text=(storage.foldername(name))[2] AND public.tax_impact_access(a.client_tenant_id)));
CREATE POLICY tax_original_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='tax-impact-originals' AND lower(storage.extension(name))='xlsx' AND EXISTS (SELECT 1 FROM public.tax_impact_analyses a WHERE a.client_tenant_id::text=(storage.foldername(name))[1] AND a.id::text=(storage.foldername(name))[2] AND public.tax_impact_access(a.client_tenant_id)));
CREATE POLICY tax_original_delete_unregistered ON storage.objects FOR DELETE TO authenticated USING (bucket_id='tax-impact-originals' AND EXISTS (SELECT 1 FROM public.tax_impact_analyses a WHERE a.client_tenant_id::text=(storage.foldername(name))[1] AND a.id::text=(storage.foldername(name))[2] AND public.tax_impact_access(a.client_tenant_id)) AND NOT EXISTS (SELECT 1 FROM public.tax_impact_imports i WHERE i.storage_path=name));